from abc import ABC, abstractmethod
import torch.utils.data


class IDataLoader(ABC):
    """Interface for data loaders."""

    @abstractmethod
    def load_data(self):
        """Return a DataLoader instance."""
        pass

    @abstractmethod
    def __len__(self):
        """Return number of batches."""
        pass


class IDatasetFactory(ABC):
    """Interface for dataset factories."""

    @abstractmethod
    def get_by_name(self, dataset_name, *args, **kwargs):
        """Return a dataset instance by name."""
        pass


class IDataset(ABC, torch.utils.data.Dataset):
    """Interface for datasets."""

    @abstractmethod
    def name(self):
        """Return dataset name."""
        pass

    @abstractmethod
    def path(self):
        """Return dataset path."""
        pass

    @abstractmethod
    def get_transform(self, opt, *args, **kwargs):
        """Return transform function."""
        pass
